import os
import json
import time
from sentence_transformers import CrossEncoder

# =============================================================================
# NEURAL RE-RANKER (Stage 2)
# -----------------------------------------------------------------------------
# Takes the Top 100 generated by BM25, extracts the original texts, and uses a 
# multilingual Cross-Encoder neural model to re-rank the documents based on 
# their true semantic meaning.
# =============================================================================

def main():
    print("=== Starting Neural Re-ranking ===")
    
    # 1. PATH SETUP
    SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
    # Adjust the base directory navigation if necessary based on your folder structure
    BASE_DIR = os.path.abspath(os.path.join(SCRIPT_DIR, "..", "..")) 
    DOCS_PATH = os.path.join(BASE_DIR, "experiment", "docs")
    RUNS_PATH = os.path.join(BASE_DIR, "experiment", "runs")
    
    COLLECTION_FILE = os.path.join(DOCS_PATH, "collection.jsonl")
    #BM25_RUN_FILE = os.path.join(RUNS_PATH, "run-native-analyzers.txt")
    BM25_RUN_FILE = os.path.join(RUNS_PATH, "run-native-analyzers-prf.txt")
    #OUTPUT_RUN_FILE = os.path.join(RUNS_PATH, "run-neural-reranked.txt")
    OUTPUT_RUN_FILE = os.path.join(RUNS_PATH, "run-neural-reranked-prf.txt")    

    # 2. LOADING DATA INTO MEMORY (Dictionaries)
    print("1. Loading document collection (into RAM)...")
    docs_dict = {}
    with open(COLLECTION_FILE, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                item = json.loads(line)
                # Combine title and abstract for the neural network to read
                doc_text = item.get("title", "") + " " + item.get("abstract", "")
                docs_dict[str(item.get("pubkey"))] = doc_text

    print("2. Loading original queries...")
    queries_dict = {}
    for lang in ["en", "de", "fr"]:
        query_file = os.path.join(DOCS_PATH, f"{lang}_dev.jsonl")
        if os.path.exists(query_file):
            with open(query_file, 'r', encoding='utf-8') as f:
                for line in f:
                    if line.strip():
                        item = json.loads(line)
                        q_id = f"{lang.upper()}_{item.get('index')}"
                        # Super basic cleaning: the neural network likes natural sentences!
                        queries_dict[q_id] = item.get("text", "").replace('\n', ' ')

    print("3. Loading BM25 results...")
    run_dict = {} # Format: { "EN_1": ["docA", "docB", ...], ... }
    with open(BM25_RUN_FILE, 'r', encoding='utf-8') as f:
        for line in f:
            parts = line.split()
            if len(parts) >= 4:
                q_id = parts[0]
                doc_id = parts[2]
                if q_id not in run_dict:
                    run_dict[q_id] = []
                # Keep only the documents retrieved for this specific query
                run_dict[q_id].append(doc_id)

    # 3. LOADING THE NEURAL MODEL
    print("\n4. Loading the Multilingual Cross-Encoder...")
    # The max_length parameter truncates overly long papers to 512 tokens to avoid running out of RAM
    model = CrossEncoder('cross-encoder/mmarco-mMiniLMv2-L12-H384-v1', max_length=512, device='cuda')
    
    # 4. RE-RANKING
    print("5. Starting semantic evaluation...")

    # --- Check processing history for Resume capability ---
    processed_queries = set()
    if os.path.exists(OUTPUT_RUN_FILE):
        with open(OUTPUT_RUN_FILE, 'r', encoding='utf-8') as f:
            for line in f:
                q_id = line.split()[0]
                processed_queries.add(q_id)
                
    if processed_queries:
        print(f" > Found {len(processed_queries)} already re-ranked queries. Resuming from where I left off!")
    # -----------------------------------------------------------
    
    start_time = time.time()
    
    # Use 'a' (append) instead of 'w' (write) to append to the end!
    with open(OUTPUT_RUN_FILE, 'a', encoding='utf-8') as out_file:
        total_queries = len(run_dict)
        
        for i, (q_id, doc_ids) in enumerate(run_dict.items(), 1):
            
            # If the query is already in the output file, skip it!
            if q_id in processed_queries:
                continue
                
            query_text = queries_dict.get(q_id, "")
            
            pairs = []
            valid_doc_ids = []
            
            # Cut to 100 documents to speed up the GPU
            for d_id in doc_ids[:100]:
                if d_id in docs_dict:
                    pairs.append([query_text, docs_dict[d_id]])
                    valid_doc_ids.append(d_id)
            
            if not pairs:
                continue

            # Batch_size 256 maximizes GPU performance
            scores = model.predict(pairs, batch_size=256)
            
            results = list(zip(valid_doc_ids, scores))
            results.sort(key=lambda x: x[1], reverse=True)
            
            for rank, (doc_id, score) in enumerate(results):
                line = f"{q_id}\tQ0\t{doc_id}\t{rank}\t{score:.6f}\trun-neural-reranked\n"
                out_file.write(line)
            
            # Ensures immediate saving to the hard drive at each cycle
            out_file.flush() 
                
            if i % 10 == 0:
                print(f" > Processed {i}/{total_queries} queries...")

    elapsed = int(time.time() - start_time)
    print(f"\n=== Re-ranking completed in {elapsed} seconds! ===")
    print(f"The new results are saved in: {OUTPUT_RUN_FILE}")
    print("You can now run evaluate.py on this new file!")

if __name__ == "__main__":
    main()